  "mcp.quick_connect_dingduff_desc": "Právní rešerše v prostém jazyce od DingDuff — miliony soudních rozhodnutí, federální a státní zákony a pravidla a podání z PACER. Přihlášení jedním kliknutím účtem DingDuff.",
