  "mcp.quick_connect_dropbox_desc": "Vyhledávejte, čtěte a spravujte soubory spisů v Dropboxu kanceláře pomocí svého účtu Dropbox.",
  "mcp.quick_connect_dropbox_note": "Vyžaduje registrovanou aplikaci Dropbox. Před přihlášením zadejte její app key jako ID klienta OAuth a její app secret.",
  "mcp.quick_connect_dropbox_title": "Dropbox",
  "mcp.quick_connect_egnyte_desc": "Vyhledávejte a shrnujte dokumenty v úložišti Egnyte kanceláře podle stávajících oprávnění Egnyte.",
  "mcp.quick_connect_egnyte_title": "Egnyte",
  "mcp.quick_connect_everlaw_desc": "Dotazujte se na dokumenty, pořadače a Bates metadata v eDiscovery projektech Everlaw kanceláře. Endpoint USA — OAuth povoluje správce organizace.",
  "mcp.quick_connect_everlaw_title": "Everlaw",
  "mcp.quick_connect_google_cloud_storage_desc": "Čtěte a zapisujte soubory spisů v bucketech Google Cloud Storage kanceláře podle oprávnění IAM.",
  "mcp.quick_connect_google_cloud_storage_title": "Google Cloud Storage",
  "mcp.quick_connect_highq_desc": "Přístup pouze pro čtení k webům, dokumentům a iSheets HighQ kanceláře. Zadejte svou instanci a web HighQ.",
  "mcp.quick_connect_highq_title": "Thomson Reuters HighQ",
  "mcp.quick_connect_imanage_desc": "Vyhledávejte dokumenty a pracovní prostory v iManage DMS kanceláře s informačními bariérami a auditem každého volání. Službu MCP povoluje správce.",
  "mcp.quick_connect_imanage_title": "iManage",
  "mcp.quick_connect_ironclad_desc": "Vyhledávání běžným jazykem ve smlouvách kanceláře v Ironclad v rozsahu oprávnění. Zobrazen endpoint pro Severní Ameriku.",
  "mcp.quick_connect_ironclad_title": "Ironclad",
  "mcp.quick_connect_legalmemory_desc": "Vlastní znalostní index vaší kanceláře od Eigenwelt Labs, tvůrců LegalWork. Vyhledávejte v dřívějších spisech, precedentech, záznamech o rozhodnutích, subjektech a fakturaci v rozsahu svých oprávnění.",
  "mcp.quick_connect_legalmemory_note": "Vyžaduje aktivní nasazení LegalMemory. Zadáte jeho základní URL a poté se přihlásíte účtem kanceláře.",
  "mcp.quick_connect_legalmemory_title": "LegalMemory",
  "mcp.quick_connect_learn_more": "Zjistit více",
  "mcp.quick_connect_featured": "Eigenwelt Labs",
  "mcp.quick_connect_netdocuments_desc": "Vyhledávejte a načítejte dokumenty z NetDocuments DMS kanceláře. Přihlaste se účtem ndMAX Enterprise.",
  "mcp.quick_connect_netdocuments_title": "NetDocuments",
  "mcp.quick_connect_notion_desc": "Stránky, databáze a projektová dokumentace v synchronizaci.",
  "mcp.quick_connect_notion_title": "Notion",
  "mcp.quick_connect_legalwork_admin_desc": "Analytika Den pouze pro čtení pro správce platformy LegalWork: růst, retence, vyhledávání společností a ad-hoc dotazy. Vyžaduje účet správce na seznamu povolených. Zkuste: \"Jaký je náš týdenní růst registrací?\"",
  "mcp.quick_connect_legalwork_admin_title": "Analytika pro správce LegalWork",
  "mcp.quick_connect_legalwork_cloud_desc": "Spravujte svou organizaci, workery, skills, poskytovatele a týmovou konfiguraci z chatu. Zkuste: \"Vypiš všechny workery v mé organizaci\" nebo \"Odešli tento skill týmu.\"",
  "mcp.quick_connect_legalwork_cloud_title": "Ovládání LegalWork Cloud",
  "mcp.quick_connect_legalwork_ui_desc": "Umožněte agentům vidět a ovládat aplikaci LegalWork. Procházejte chaty, pište do pole pro psaní, otevírejte nastavení. Zkuste: \"Pořiď snímek toho, co vidím\" nebo \"Vytvoř nový chat a napiš ahoj.\"",
  "mcp.quick_connect_legalwork_ui_title": "Ovládání rozhraní LegalWork",
  "mcp.quick_connect_relativity_desc": "Dotazujte se na eDiscovery instanci RelativityOne kanceláře přirozeným jazykem — spravujte spisy, pracovní prostory a přístupy. Zadejte hostname svého tenantu a Client ID od podpory Relativity; vystupujete jako přihlášený systémový administrátor.",
  "mcp.quick_connect_relativity_title": "Relativity",
  "mcp.quick_connect_ruly_desc": "Vyhledávejte soudní řády, místní pravidla soudů a procesní předpisy dané jurisdikce s podloženými citacemi. Přihlášení jedním kliknutím účtem Ruly; vyžaduje aktivní předplatné MCP.",
  "mcp.quick_connect_ruly_title": "Ruly",
  "mcp.quick_connect_sharepoint_desc": "Vyhledávejte a spravujte soubory spisů na webech SharePoint a v OneDrive kanceláře. Zadejte ID svého tenantu; vyžaduje souhlas správce.",
  "mcp.quick_connect_sharepoint_title": "Microsoft SharePoint",
  "mcp.quick_connect_taxgraph_desc": "Prohledávejte denně aktualizovaný znalostní graf německého daňového práva — zákony, judikaturu BFH a pokyny BMF s citacemi.",
  "mcp.quick_connect_taxgraph_title": "TaxGraph",
