  "tool_permissions.desc": "Rozhodněte, co smí LegalWork dělat samostatně a kdy se vás musí nejprve zeptat. Tato nastavení platí pro všechny pracovní prostory.",
  "tool_permissions.ask_before_edit": "Ptát se před úpravou souborů",
