  "projects.setup.create": "Vytvořte a nastavte",
  "projects.setup.initial_prompt": "Nastavte tohoto klienta z jeho existujících místních a/nebo propojených vzdálených složek. Nejprve použijte legalwork_project_get_details k nalezení skutečných polí metadat, včetně mých vlastních polí, typů, povolených možností a existujících hodnot. Procházejte složky a čtěte relevantní přístupné dokumenty. Dejte klientovi vhodný název a naplňte podporovaná metadata pomocí legalwork_project_set_metadata, přičemž zachováte moje definice polí a existující hodnoty a neznámé skutečnosti ponecháte prázdné. Zkontrolujte existující úkoly a poznámky klienta, abyste se vyhnuli duplicitám. Vytvořte konkrétní nevyřízené úkoly podporované dokumenty pomocí legalwork_task_create(linkToProject=true), včetně odkazů na zdroje a pouze podporovaných dat. Pokud jsou ve zdrojích přítomny užitečné poznámky, přidejte několik stručných, přiřazených poznámek pomocí legalwork_project_create_note; nevytvářejte poznámky pro každý dokument ani neduplikujte poznámky, které již jsou v prostředí Notes. Dokončete znovu přečtením aktuální revize a označte nastavení jako dokončené pomocí legalwork_project_complete_setup. Nevytvářejte ani neukládejte samostatné shrnutí klienta. Po přejmenování nepřestávejte. Stručně vysvětlete, co jste přidali, co nebylo možné odvodit a případné mezery v přístupu nebo hledání. Nezrcadlte ani neindexujte zdrojové složky.",
