  "scheduled.template_brief": "Ranní přehled spisu",
  "scheduled.template_brief_description": "Shrne otevřené úkoly, blížící se lhůty a položky vyžadující pozornost.",
  "scheduled.template_brief_prompt": "Projděte úkoly a kalendář tohoto klienta. Shrňte blížící se lhůty, otevřenou práci a položky, které vyžadují mou pozornost. Uveďte odkazy na zdrojové záznamy. Neměňte lhůty ani neposílejte zprávy.",
  "scheduled.template_deadlines": "Kontrola blížících se lhůt",
  "scheduled.template_deadlines_description": "Zkontroluje lhůty a chybějící informace na nejbližších sedm dní.",
  "scheduled.template_deadlines_prompt": "Projděte kalendář a úkoly tohoto klienta a najděte lhůty v nejbližších sedmi dnech. Označte chybějící informace nebo kolize k mé kontrole a uveďte odkazy na zdrojové záznamy. Lhůty nepočítejte, nevytvářejte ani neměňte a neposílejte zprávy.",
  "scheduled.template_planning": "Týdenní plánování",
  "scheduled.template_planning_description": "Navrhne priority a plán úkolů a lhůt na příští týden.",
  "scheduled.template_planning_prompt": "Projděte otevřené úkoly a kalendář tohoto klienta na nadcházející týden. Navrhněte priority, určete blížící se lhůty a závislosti a nastiňte praktický týdenní plán. Uveďte odkazy na zdrojové záznamy. Nevytvářejte ani neměňte úkoly či lhůty a neposílejte zprávy.",
  "scheduled.template_review": "Týdenní revize znalostí pro wiki",
  "scheduled.template_review_description": "Najde užitečné znalosti z chatů u klientů za minulý týden a připraví návrhy do wiki k vaší kontrole.",
  "scheduled.template_review_prompt": "Projděte chaty za posledních sedm dní u všech dostupných klientů a porovnejte užitečná zjištění s dostupnými wiki. Před výběrem příspěvků si přečtěte pokyny cílové wiki a relevantní stránky. Upřednostněte užitečná fakta o organizacích a vztazích, věcná zjištění a nezřejmé postupy, které pomohou při budoucí práci. Dávejte přednost cíleným aktualizacím existujících stránek; vynechte obecné kontrolní seznamy, samozřejmé rady a již pokryté informace. Neexistuje žádná kvóta, a pokud nejsou hodnotná doplnění, nevzniknou žádné koncepty. Je-li to vhodné pro publikum wiki, ponechte relevantní identity; obecná poučení podle potřeby anonymizujte; nekopírujte klientské dokumenty ani záznamy chatů. Vynechte vlastní chaty této revize a předchozí automatizované revize. Kde je to vhodné, znovu použijte čekající návrhy a neopakujte zamítnuté nápady. Každý koncept ponechte u tohoto klienta s navrhovanou cílovou wiki a stránkou, aby jej bylo možné upravit, uložit nebo zamítnout. Nic nepublikujte. Veďte krátký plán postupu a na závěr uveďte odkazy na koncepty a stručné shrnutí pokrytí, nebo oznamte, že nebylo nalezeno nic užitečného.",
  "scheduled.templates_hint": "Před uložením upravte pokyny a plánování.",
